  var where = [place0, meta.year && !/\b(1[5-9]\d\d|20\d\d)\b/.test(String(place0 || "")) ? meta.year : null].filter(Boolean).join(", ");
  out.intro = (where ? where + ". " : "") + (displayName(meta.white) || "White") + " against " + (displayName(meta.black) || "Black") + ".";
