    if (t.indexOf("mate") >= 0 && th.indexOf("smotheredMate") >= 0) txt = pickOne([bare + "# A smothered mate!", "Smothered mate with " + bare + "!"], s);
    else if (t.indexOf("mate") >= 0 && th.indexOf("backRankMate") >= 0) txt = pickOne([bare + "# Back-rank mate!", "Back-rank mate with " + bare + "!"], s);
    else if (t.indexOf("mate") >= 0) txt = pickOne([bare + ". Checkmate!", bare + " is checkmate.", "Checkmate with " + bare + "!"], s);
