      id: r.id, white: m.white + (m.whiteElo ? " (" + m.whiteElo + ")" : ""), black: m.black + (m.blackElo ? " (" + m.blackElo + ")" : ""),
      event: m.event, place: m.place, year: m.year, result: m.result, opening: m.opening, moves: r.plyCount ? Math.ceil(r.plyCount / 2) : undefined
