function refreshDerived(r) {
  if (!r || !r.moments || !r.moves) return r;
  if (r.moments.every(function (m) { return m.themes; }) && r.themes) return r;
  var game; try { game = buildGame(r.moves, r.startFen); } catch (e) { return r; }
  r.moments.forEach(function (m) {
    if (m.themes || !game.plies[m.ply - 1]) return;
    var t = moveThemes(game, m.ply);
    if (m.tags.indexOf("sacrifice") >= 0 || m.tags.indexOf("brilliant") >= 0) t.unshift("sacrifice");
    if (m.tags.indexOf("forcedMate") >= 0) t.push("mateIn");
    m.themes = t.filter(function (x, i, a) { return a.indexOf(x) === i; });
  });
  r.themes = reelThemes(r.moments);
  return r;
}
